func (c *Checker) checkDefinition(def ast.Definition) {
	switch d := def.(type) {
	case *ast.FunctionDef:
		c.checkFunctionDef(d)
	case *ast.ExternDef:
		c.checkExternDef(d)
	case *ast.StructDef:
		c.checkStructDef(d)
	case *ast.TypeDef:
		c.checkTypeDef(d)
	case *ast.InterfaceDef:
